class Solution {public int solve(int[][] g){int m=g.length,n=m==0?0:g[0].length;if(n==0)return 0;int[][] id=new int[m][n];for(int[] row:id)Arrays.fill(row,-1);ArrayList<Integer> size=new ArrayList<>();int[] dr={-1,1,0,0},dc={0,0,-1,1};int best=0;for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(g[r][c]==1&&id[r][c]<0){int label=size.size();ArrayList<int[]>q=new ArrayList<>();q.add(new int[]{r,c});id[r][c]=label;for(int i=0;i<q.size();i++)for(int k=0;k<4;k++){int x=q.get(i)[0]+dr[k],y=q.get(i)[1]+dc[k];if(x>=0&&x<m&&y>=0&&y<n&&g[x][y]==1&&id[x][y]<0){id[x][y]=label;q.add(new int[]{x,y});}}size.add(q.size());best=Math.max(best,q.size());}for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(g[r][c]==0){HashSet<Integer> near=new HashSet<>();for(int k=0;k<4;k++){int x=r+dr[k],y=c+dc[k];if(x>=0&&x<m&&y>=0&&y<n&&id[x][y]>=0)near.add(id[x][y]);}int value=1;for(int label:near)value+=size.get(label);best=Math.max(best,value);}return best;}}